from neo4j import GraphDatabase

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(session, *args, **kwargs):
            with session.begin_transaction(metadata=metadata, timeout=timeout) as tx:
                return func(tx, *args, **kwargs)
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f'Key {key} not found in the list')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._record.values())
    else:
        return [self._record[key] for key in keys if key in self._record]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._data)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields[key]] = self._data[key]
        elif isinstance(key, str):
            result[key] = self._data.get(key, None)
        else:
            raise TypeError(f"Invalid key type: {type(key)}")

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    from neo4j import GraphDatabase
    from neo4j.packstream import Packer, Unpacker

    # Assuming self.driver is a GraphDatabase driver instance
    with self.driver.session() as session:
        result = session.run("DISCARD", n=n, qid=qid)
        response = Response(result, dehydration_hooks=dehydration_hooks, hydration_hooks=hydration_hooks, **handlers)
        return response

class Response:
    def __init__(self, result, dehydration_hooks=None, hydration_hooks=None, **handlers):
        self.result = result
        self.dehydration_hooks = dehydration_hooks or {}
        self.hydration_hooks = hydration_hooks or {}
        self.handlers = handlers

    def __iter__(self):
        for record in self.result:
            yield self._hydrate_record(record)

    def _hydrate_record(self, record):
        hydrated_record = {}
        for key, value in record.items():
            hydrated_record[key] = self._hydrate_value(value)
        return hydrated_record

    def _hydrate_value(self, value):
        value_type = type(value)
        if value_type in self.hydration_hooks:
            return self.hydration_hooks[value_type](value)
        return value

