def point_type(name: str, fields: List[Tuple[str, type]], srid_map: Dict[int, str]):
    """Dynamically create a Point subclass."""
    if not all(len(f) == 2 for f in fields):
        raise ValueError("Fields must be a list of (name, type) tuples.")

    field_names = [f[0] for f in fields]
    field_types = {f[0]: f[1] for f in fields}

    if 'srid' in field_names:
        raise ValueError("Field name 'srid' is reserved.")

    def __init__(self, **kwargs):
        for field_name in field_names:
            if field_name not in kwargs:
                raise TypeError(f"Missing required argument: {field_name}")
            setattr(self, field_name, kwargs[field_name])
        self.srid = kwargs.get('srid', 4326)

    def __repr__(self):
        field_values = ', '.join(f"{name}={getattr(self, name)!r}" for name in field_names)
        return f"{name}({field_values}, srid={self.srid!r})"

    # Create a new class with the specified fields
    new_class = type(name, (Point,), {
        **{field_name: field(default=None, type=field_type) for field_name, field_type in field_types.items()},
        '__init__': __init__,
        '__repr__': __repr__,
    })

    return new_class

