        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if extract_spec_version:
            type_value = inventory.get('type')
            if type_value and re.match(r'^v\d+\.\d+$', type_value):
                self.spec_version = type_value

        # Example validation logic, replace with actual validation rules
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        if 'items' not in inventory:
            raise KeyError("Inventory must contain 'items' key")

        if not isinstance(inventory['items'], list):
            raise ValueError("Inventory 'items' must be a list")

        for item in inventory['items']:
            if not isinstance(item, dict):
                raise ValueError("Each item in inventory must be a dictionary")

            if 'name' not in item:
                raise KeyError("Each item must contain 'name' key")

            if 'quantity' not in item:
                raise KeyError("Each item must contain 'quantity' key")

            if not isinstance(item['quantity'], int) or item['quantity'] < 0:
                raise ValueError("Item 'quantity' must be a non-negative integer")

