class ExpressionAbsorber:
    def __init__(self):
        pass

    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        from collections import deque

        def apply_absorption(expr):
            stack = deque()
            operators = {'&', '|'}
            for term in expr:
                if term in operators:
                    stack.append(term)
                else:
                    if len(stack) >= 3 and stack[-1] in operators:
                        op1 = stack.pop()
                        b = stack.pop()
                        op2 = stack.pop()
                        a = stack.pop()
                        if op1 == '|' and op2 == '&' and a == b:
                            stack.append(a)
                        elif op1 == '&' and op2 == '|' and a == b:
                            stack.append(a)
                        elif op1 == '|' and op2 == '&' and a == f'~{b}':
                            stack.append(f'{a} & {b}')
                        elif op1 == '&' and op2 == '|' and a == f'~{b}':
                            stack.append(f'{a} | {b}')
                        else:
                            stack.append(a)
                            stack.append(op2)
                            stack.append(b)
                            stack.append(op1)
                    stack.append(term)
            return list(stack)

        return [apply_absorption(expr) for expr in args]

