from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    merged_dict = defaultdict(lambda: (None, None))

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, MappingNode):
            if merged_dict[key][0] is None:
                merged_dict[key] = (key_node, defaultdict(lambda: (None, None)))
            _, merged_value_dict = merged_dict[key]
            for sub_key_node, sub_value_node in value_node.value:
                sub_key = sub_key_node.value
                merged_value_dict[sub_key] = (sub_key_node, sub_value_node)
        else:
            merged_dict[key] = (key_node, value_node)

    result = []
    for key_node, value in merged_dict.values():
        if isinstance(value, tuple) and isinstance(value[1], defaultdict):
            merged_value_node = MappingNode(tag='tag:yaml.org,2002:map', value=[
                (sub_key_node, sub_value_node) for sub_key_node, sub_value_node in value[1].values()
            ])
            result.append((key_node, merged_value_node))
        else:
            result.append((key_node, value))

    return result

