def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if isinstance(base, type):
            metaclasses.add(base.__class__)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common base
    common_base = None
    for m in metaclasses:
        if common_base is None:
            common_base = m
        else:
            common_base = common_base.__mro__[1]
            while common_base is not object:
                if issubclass(m, common_base):
                    break
                common_base = common_base.__mro__[1]
            else:
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

    return common_base

class Dictator:
    def __init__(self):
        self._data = {}

    def pop(self, key, default=__import__('functools').partial(lambda: None)()):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key in self._data:
            return self._data.pop(key)
        if default is not __import__('functools').partial(lambda: None)():
            return default
        raise KeyError(key)

