import requests

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    full_url = f"{url}{document_path}"
    response = requests.get(full_url)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to retrieve NodeInfo document: {response.status_code}")

import json
from xml.etree import ElementTree as ET
from typing import Dict, Optional

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "links": {link["rel"]: link["href"] for link in data.get("links", [])}
        }
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            subject = root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text
            aliases = [alias.text for alias in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias")]
            links = {}
            for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    links[rel] = href
            return {
                "subject": subject,
                "aliases": aliases,
                "links": links
            }
        except (ET.ParseError, AttributeError):
            return {}

import os

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    file_names.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(file_names)

