import yaml
from jsonschema import validate, ValidationError

class IRValidatorException(Exception):
    pass

class SpecValidator:
    @classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content cannot be None")

        try:
            spec_data = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML content: {e}")

        schema = {
            "type": "object",
            "required": ["required_field1", "required_field2"],  # Replace with actual required fields
            "properties": {
                "required_field1": {"type": "string"},
                "required_field2": {"type": "string"},
                # Add other fields and their types as necessary
            }
        }

        try:
            validate(instance=spec_data, schema=schema)
        except ValidationError as ve:
            raise IRValidatorException(f"Validation error: {ve.message}")

        return spec_data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import os
    import yaml

    def load_yaml_file(file_path):
        with open(file_path, 'r') as file:
            return yaml.safe_load(file)

    if 'include' in parser_dict:
        include_paths = parser_dict.pop('include')
        if not isinstance(include_paths, list):
            include_paths = [include_paths]

        for path in include_paths:
            if os.path.exists(path):
                included_dict = load_yaml_file(path)
                parser_dict.update(included_dict)
            else:
                raise FileNotFoundError(f"Include file not found: {path}")
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for key, value in self.spec.items():
        if isinstance(value, dict) and 'default' in value:
            defaults[key] = value['default']
        elif not isinstance(value, dict):
            defaults[key] = value
    return defaults

