import warnings

class ArgumentValidator:
    def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        deprecated_args = {
            'old_arg1': 'new_arg1',
            'old_arg2': 'new_arg2'
        }

        all_args = {**cli_args, **answer_file_args}

        for old, new in deprecated_args.items():
            if old in all_args:
                warnings.warn(
                    f"Argument '{old}' has been deprecated in favor of '{new}'. "
                    f"'{old}' will be removed in a future version.",
                    category=DeprecationWarning,
                    stacklevel=2
                )
                if new not in all_args:
                    all_args[new] = all_args.pop(old)
                else:
                    del all_args[old]

