import argparse

class CommandParser:
    def __init__(self):
        self.parsers = {
            'main': self._get_main_options,
            'virsh': self._get_virsh_options,
            'ospd': self._get_ospd_options,
        }

    def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        if command_name in self.parsers:
            return self.parsers[command_name]()
        else:
            raise ValueError(f"Unknown command: {command_name}")

    def _get_main_options(self):
        parser = argparse.ArgumentParser(description='Main command options')
        parser.add_argument('--verbose', action='store_true', help='Enable verbose output')
        parser.add_argument('--config', type=str, help='Path to configuration file')
        return parser

    def _get_virsh_options(self):
        parser = argparse.ArgumentParser(description='Virsh command options')
        parser.add_argument('--connect', type=str, help='Hypervisor connection URI')
        parser.add_argument('--domain', type=str, help='Domain name or ID')
        return parser

    def _get_ospd_options(self):
        parser = argparse.ArgumentParser(description='OSPD command options')
        parser.add_argument('--port', type=int, default=12320, help='Port to listen on')
        parser.add_argument('--address', type=str, default='127.0.0.1', help='Address to listen on')
        return parser

